<script setup lang="ts">const {lang}=useLocale(); const {data:services}=await useFetch<any[]>('/api/catalog/services'); const q=ref(''); const page=ref(1); const filtered=computed(()=>services.value?.filter(s=>`${s.nameRu} ${s.nameEn} ${s.code}`.toLowerCase().includes(q.value.toLowerCase()))||[]); const visible=computed(()=>filtered.value.slice(0,page.value*60)); usePageSeo(computed(()=>lang.value==='ru'?'Сервисы для приёма SMS':'Services for receiving SMS'),computed(()=>lang.value==='ru'?'Каталог сервисов для просмотра кодов подтверждения.':'Catalog of services for browsing verification codes.'))</script>
<template><div class="shell page"><span class="kicker">Catalog / 800+</span><h1>{{lang==='ru'?'Сервисы и приложения':'Services and apps'}}</h1><p class="lead">{{lang==='ru'?'Выберите приложение, для которого хотите изучить доступные направления и публичные номера.':'Choose the app whose available destinations and public numbers you want to explore.'}}</p><input v-model="q" class="search" :placeholder="lang==='ru'?'Telegram, WhatsApp, Google…':'Telegram, WhatsApp, Google…'"><div class="card-grid"><ServiceCard v-for="s in visible" :key="s.code" :service="s"/></div><button v-if="visible.length<filtered.length" class="button more" @click="page++">{{lang==='ru'?'Показать ещё':'Show more'}}</button></div></template>
